import asyncio
import functools
import logging
import random
import time
import requests

logger = logging.getLogger(__name__)

# HTTP status codes that are considered retryable
RETRYABLE_HTTP_CODES = {429, 502, 503, 504}

# Exception types that are considered retryable
RETRYABLE_EXCEPTIONS = (requests.exceptions.Timeout, requests.exceptions.ConnectionError)

def _is_retryable(exception):
    """Check if the exception should trigger a retry."""
    if isinstance(exception, RETRYABLE_EXCEPTIONS):
        return True
    # Check for HTTPError with retryable status code
    if isinstance(exception, requests.exceptions.HTTPError):
        if exception.response is not None and exception.response.status_code in RETRYABLE_HTTP_CODES:
            return True
    return False

def retry_with_backoff(max_attempts=5, base_delay=1.0):
    """
    Decorator that retries a function with exponential backoff and jitter.

    Retries on connection errors, timeouts, and HTTP 429/502/503/504.
    Works with both sync and async functions.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    attempt += 1
                    if attempt >= max_attempts or not _is_retryable(exc):
                        raise
                    # Calculate delay with exponential backoff and jitter
                    delay = base_delay * (2 ** (attempt - 1))
                    # Add jitter: ±20% of the delay
                    jitter = random.uniform(-0.2 * delay, 0.2 * delay)
                    sleep_time = max(0, delay + jitter)
                    logger.warning(
                        f"Attempt {attempt}/{max_attempts} failed: {exc}. Retrying in {sleep_time:.2f}s."
                    )
                    time.sleep(sleep_time)

        @functools.wraps(func)
        async def async_wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return await func(*args, **kwargs)
                except Exception as exc:
                    attempt += 1
                    if attempt >= max_attempts or not _is_retryable(exc):
                        raise
                    delay = base_delay * (2 ** (attempt - 1))
                    jitter = random.uniform(-0.2 * delay, 0.2 * delay)
                    sleep_time = max(0, delay + jitter)
                    logger.warning(
                        f"Attempt {attempt}/{max_attempts} failed: {exc}. Retrying in {sleep_time:.2f}s."
                    )
                    await asyncio.sleep(sleep_time)

        if asyncio.iscoroutinefunction(func):
            return async_wrapper
        else:
            return wrapper
    return decorator
EOF"}

