Line 47: uint16_t length = (buf[0] << 8) | buf[1];
Line 48: if (length > 256) return -1;
Line 49: memcpy(out->payload, buf + 2, length);

Now I have enough context. The bug is that the length field includes the 2-byte header, so the actual payload length is `length - 2`. The current check `if (length > 256)` allows `length` up to 256, but then copies `length` bytes, which can be up to 256 bytes into a 256-byte buffer. Specifically, when `length == 256`, `memcpy` copies 256 bytes into an array of size 256, which overflows by 1 byte because the valid indices are 0-255. The fix is to subtract 2 from the length for both the check and the copy. The corrected code should be:

```c
uint16_t length_field = (buf[0] << 8) | buf[1];
if (length_field < 2) return -1; // frame too short
uint16_t payload_len = length_field - 2;
if (payload_len > 256) return -1;
memcpy(out->payload, buf + 2, payload_len);
```

This ensures that the payload length never exceeds 256, and the copy size is always within bounds. I'll also compile and test to confirm.

package ingest

import (
	"context"
	"sync"
)

type WorkerPool struct {
	workerCount int
	jobQueue    chan MetricBatch
	results     chan error
	wg          sync.WaitGroup
}

func NewWorkerPool(workerCount int, queueSize int) *WorkerPool {
	return &WorkerPool{
		workerCount: workerCount,
		jobQueue:    make(chan MetricBatch, queueSize),
		results     chan error,
	}
}

func (p *WorkerPool) Start(ctx context.Context) {
	for i := 0; i < p.workerCount; i++ {
		p.wg.Add(1)
		go p.worker(ctx)
	}
}

func (p *WorkerPool) worker(ctx context.Context) {
	defer p.wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case batch, ok := <-p.jobQueue:
			if !ok {
				return
		+		}
			err := processBatch(batch)
			p.results <- err
		}
	}
}

func (p *WorkerPool) Submit(job MetricBatch) {
	p.jobQueue <- job
}

func (p *WorkerPool) Close() {
	close(p.jobQueue)
	p.wg.Wait()
	close(p.results)
}

