import random
import time
import httpx

def retry_with_backoff(max_attempts=4, base_delay=0.5, factor=2, jitter=0.1):
    def decorator(func):
        @functools.wraps(func)
        async def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return await func(*args, **kwargs)
                except (httpx.TransportError, httpx.HTTPStatusError) as exc:
                    if isinstance(exc, httpx.HTTPStatusError):
                        if exc.response.status_code not in (502, 503, 504):
                            raise
                    attempt += 1
                    if attempt >= max_attempts:
                        raise
                    delay = base_delay * (factor ** (attempt - 1)) + random.uniform(-jitter, jitter)
                    print(f"Attempt {attempt} failed: {exc}. Retrying in {delay:.2f}s...")
                    await asyncio.sleep(delay)
        return wrapper
    return decorator
"
}

