{"path": "rate_limit.go", "content": "package main

import (
	"encoding/json"
	"net"
	"net/http"
	"sync"
	"time"
)

// RateLimiter implements token bucket rate limiting per IP.
// Usage: rl := NewRateLimiter(10.0/60.0, 5) // 10 req/min with burst 5
// Then wrap your handler: http.Handle("/", rl.Middleware(yourHandler))
type RateLimiter struct {
	mu sync.Mutex
	rate float64 // tokens per second
	burst int
	buckets map[string]*bucket
}

type bucket struct {
	tokens float64
	last time.Time
}

func NewRateLimiter(rate float64, burst int) *RateLimiter {
	return &RateLimiter{
		rate: rate,
		burst: burst,
		buckets: make(map[string]*bucket),
	}
}

func (rl *RateLimiter) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ip := getIP(r.RemoteAddr)
		rl.mu.Lock()
		b, ok := rl.buckets[ip]
		if !ok {
			b = &bucket{tokens: float64(rl.burst), last: time.Now()}
			rl.buckets[ip] = b
		}
		now := time.Now()
		// Refill tokens based on elapsed time
		if now.After(b.last) {
			elapsed := now.Sub(b.last).Seconds()
			b.tokens = min(float64(rl.burst), b.tokens + elapsed * rl.rate)
			b.last = now
		}
		if b.tokens >= 1 {
			b.tokens--
			rl.mu.Unlock()
			next.ServeHTTP(w, r)
		} else {
			retryAfter := int(time.Until(b.last.Add(time.Duration((1-b.tokens)/rl.rate * float64(time.Second)))).Seconds())
			if retryAfter < 1 {
				retryAfter = 1
			}
			rl.mu.Unlock()
			w.Header().Set("Content-Type", "application/json")
			w.Header().Set("Retry-After", fmt.Sprintf("%d", retryAfter))
			w.WriteHeader(http.StatusTooManyRequests)
			json.NewEncoder(w).Encode(map[string]string{"error": "rate limit exceeded"})
		}
	})
}

func getIP(remoteAddr string) string {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		return remoteAddr
	}
	return host
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}"}

