```js
const Book = require('./models/Book');
const Author = require('./models/Author');

const resolvers = {
  Query: {
    books: async () => {
      return await Book.find().populate('author');
    },
    book: async (_, { id }) => {
      return await Book.findById(id).populate('author');
    },
    authors: async () => {
      return await Author.find();
    },
    author: async (_, { id }) => {
      return await Author.findById(id);
    },
    booksByAuthor: async (_, { authorId }) => {
      return await Book.find({ author: authorId }).populate('author');
    }
  },
  Mutation: {
    addBook: async (_, { title, authorId, genre, publishedYear }) => {
      const book = new Book({ title, author: authorId, genre, publishedYear });
      await book.save();
      return await Book.findById(book.id).populate('author');
    }
  },
  Book: {
    author: async (book) => {
      if (book.author && book.author.name) return book.author; // already populated
      return await Author.findById(book.author);
    }
  },
  Author: {
    books: async (author) => {
      return await Book.find({ author: author.id }).populate('author');
    }
  }
};

module.exports = resolvers;
```

Note: The Book resolver for author handles the case where the book is not populated. The Author.books resolver returns books with author populated, which is fine.

