});

app.get('/tasks/:id', (req, res) => {
  const task = tasks.get(req.params.id);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.json(task);
});

app.post('/tasks', (req, res) => {
  const { title, description, status } = req.body;
  if (!title || typeof title !== 'string') {
    return res.status(400).json({ error: 'title is required and must be a string' });
  }
  const validStatuses = ['pending', 'in_progress', 'completed'];
  if (status && !validStatuses.includes(status)) {
    return res.status(400).json({ error: 'status must be one of: pending, in_progress, completed' });
  }
  const task = {
    id: uuidv4(),
    title,
    description: description || '',
    status: status || 'pending'
  };
  tasks.set(task.id, task);
  res.status(201).json(task);
});

app.put('/tasks/:id', (req, res) => {
  const task = tasks.get(req.params.id);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  const { title, description, status } = req.body;
  if (title !== undefined) {
    if (typeof title !== 'string') return res.status(400).json({ error: 'title must be a string' });
    task.title = title;
  }
  if (description !== undefined) {
    task.description = description;
  }
  if (status !== undefined) {
    const validStatuses = ['pending', 'in_progress', 'completed'];
    if (!validStatuses.includes(status)) return res.status(400).json({ error: 'invalid status' });
    task.status = status;
  }
  res.json(task);
});

app.delete('/tasks/:id', (req, res) => {
  if (!tasks.delete(req.params.id)) return res.status(404).json({ error: 'Task not found' });
  res.status(204).send();
});

if (require.main === module) {
  app.listen(3000, () => console.log('Server running on port 3000'));
}

module.exports = app;
