{"path": "game_logic.js", "content": "// game_logic.js - ported from game_logic.py

function rollDice(sides, times) {
    let sum = 0;
    for (let i = 0; i < times; i++) {
        sum += Math.floor(Math.random() * sides) + 1;
    }
    return sum;
}

function computeAttack(attacker, defender) {
    const base = attacker.strength + rollDice(6, 2);
    const armor = defender.armor;
    return Math.max(0, base - armor);
}

function takeDamage(character, damage) {
    character.hp -= damage;
    if (character.hp < 0) {
        character.hp = 0;
    }
    return character.hp;
}

function resolveTurn(player, monster) {
    const playerDamage = computeAttack(player, monster);
    if (playerDamage > 0) {
        takeDamage(monster, playerDamage);
    }
    if (monster.hp > 0) {
        const monsterDamage = computeAttack(monster, player);
        takeDamage(player, monsterDamage);
    }
    return [player, monster];
}

module.exports = { rollDice, computeAttack, takeDamage, resolveTurn };"}
